Exec_Q_Msg * exec_q_remove (Q exec_q_free)
{	
	Exec_Q_Msg * exec_q_msg = NULL ; 
	
	if( exec_q_free )
	{
		exec_q_msg = (Exec_Q_Msg *) q_remove_c (exec_q_free);
	}
			
	return exec_q_msg ;
}

